import org.ufpi.mercurycall.solvers.NonExactResult;
import org.ufpi.mercurycall.solvers.SPNsolver;
import org.ufpi.mercurycall.util.facade.utils.FacadeUtil;
import java.io.*;
import java.util.*;

/** Future-event scheduler and owner of exclusive fleet transitions. */
class SimScheduler {
    enum ExecutionMode { STATIC, DYNAMIC_DT }
    private final PriorityQueue<SimEvent> queueEvents = new PriorityQueue<>();
    private final Map<String, String> missionStates = new HashMap<>();
    private double currentTime; private boolean running;
    private double nextMetricSample = 60_000, nextDecisionCycle = 300_000, decisionInterval = 300_000;
    double simulationTime; SPNsolver spnSolver;
    final DatabaseManager monitorDT = DatabaseManager.getInstance();
    ExecutionMode mode = ExecutionMode.DYNAMIC_DT; double rechargeTime = 15_000, displacementTime = 15_000;
    /** DT target is deliberately below the SLA, leaving room for demand and travel variation. */
    double targetMmt = 2_400_000;
    /** Small ready reserve avoids returning a drone that is immediately needed by the next arrival. */
    int idleReserve = 2;
    int fixedFleetSize, pendingReturns, nextDroneId, lastRecommendedFleet;
    static class SystemState { double numDrones,tamDeposito,ad,queue,pousoDecola,voo,A,B,C,D,E,F,emprestimo,devolucao,idle; }
    void configure(ExecutionMode mode, double recharge, double displacement, double targetMmt, int idleReserve, double decisionInterval, int fleet, int nextId) { this.mode=mode; rechargeTime=recharge; displacementTime=displacement; this.targetMmt=targetMmt; this.idleReserve=Math.max(0,idleReserve); this.decisionInterval=Math.max(60_000,decisionInterval); nextDecisionCycle=this.decisionInterval; fixedFleetSize=fleet; nextDroneId=nextId; lastRecommendedFleet=fleet; }
    void schedule(String proxy, String name, double value, double delay, Runnable action) { queueEvents.add(new SimEvent(proxy,name,value,currentTime+Math.max(0,delay),action)); }
    double now() { return currentTime; } void stop() { running=false; }
    void dispatchAvailable() { if(Utils.packageQueue==null || Utils.packageQueue.isEmpty()) return; for(Drone d:new ArrayList<>(Utils.listaDeDrones)) { if(Utils.packageQueue.isEmpty()) break; if(d.state==DroneState.AVAILABLE) d.tryPickup(); } }
    void missionCompleted(Drone d) { missionStates.remove("Drone"+d.id); d.state=DroneState.RECHARGING; schedule("Drone"+d.id,"RECHARGE_COMPLETE",rechargeTime,rechargeTime,()-> { if(d.state!=DroneState.RECHARGING)return; if(d.rented&&pendingReturns>0){pendingReturns--;beginReturn(d);}else{d.state=DroneState.AVAILABLE;dispatchAvailable();} }); }
    void requestRentals(int n) { if(mode!=ExecutionMode.DYNAMIC_DT)return; for(int i=0;i<n;i++){ Drone d=new Drone(nextDroneId++,true,DroneState.RENTING_TRANSIT,Utils.packageQueue,this); Utils.listaDeDrones.add(d); schedule("Drone"+d.id,"RENTAL_ARRIVAL",displacementTime,displacementTime,()-> {if(d.state==DroneState.RENTING_TRANSIT){d.state=DroneState.AVAILABLE;dispatchAvailable();}}); } }
    void requestReturns(int n) { if(mode!=ExecutionMode.DYNAMIC_DT||n<=0)return; int left=n; for(Drone d:new ArrayList<>(Utils.listaDeDrones)){if(left==0)break;if(d.rented&&d.state==DroneState.AVAILABLE){beginReturn(d);left--;}} pendingReturns+=left; }
    private void beginReturn(Drone d) { d.state=DroneState.RETURNING_TRANSIT; schedule("Drone"+d.id,"RETURN_COMPLETE",displacementTime,displacementTime,()-> {if(d.state==DroneState.RETURNING_TRANSIT)d.state=DroneState.RETURNED;}); }
    private long count(DroneState state){return Utils.listaDeDrones.stream().filter(d->d.state==state).count();}
    private long active(){return count(DroneState.ACTIVE);} private long operational(){return active()+count(DroneState.AVAILABLE)+count(DroneState.RECHARGING);}
    private Map<String,Integer> places(){Map<String,Integer> r=new HashMap<>();for(String s:missionStates.values())r.merge(s,1,Integer::sum);return r;}
    void resetSystemStateFile(){try(BufferedWriter w=new BufferedWriter(new FileWriter("system_state_log.csv",false))){w.write("Time(ms);AD;TotalDrones;OperationalDrones;ActiveDrones;IdleDrones;RechargeDrones;RentingTransitDrones;ReturningTransitDrones;Emprestimo;Devolucao;A;B;C;D;E;F;QueueSize;MMT;Throughput;TargetMMT;RecommendedFleet\n");}catch(IOException e){throw new UncheckedIOException(e);}}
    void saveSystemState(){Map<String,Integer>p=places();long a=active(),idle=count(DroneState.AVAILABLE),recharge=count(DroneState.RECHARGING),rent=count(DroneState.RENTING_TRANSIT),ret=count(DroneState.RETURNING_TRANSIT);if(mode==ExecutionMode.STATIC&&a+idle+recharge!=fixedFleetSize)throw new IllegalStateException("Static fleet conservation violated");long placeActive=p.values().stream().mapToInt(Integer::intValue).sum();if(a!=placeActive)System.err.printf(Locale.US,"[%.0f] aviso: ActiveDrones=%d, A+B+C+D+E=%d (etapa final ainda nao possui place dedicado)%n",currentTime,a,placeActive);try(BufferedWriter w=new BufferedWriter(new FileWriter("system_state_log.csv",true))){w.write(String.format(Locale.US,"%.2f;%.4f;%d;%d;%d;%d;%d;%d;%d;%d;%d;%d;%d;%d;%d;%d;%d;%d;%.4f;%.4f;%.4f;%d%n",currentTime,monitorDT.getAverageMetricValue("system","AD"),Utils.listaDeDrones.stream().filter(d->d.state!=DroneState.RETURNED).count(),operational(),a,idle,recharge,rent,ret,rent,ret,p.getOrDefault("POUSO_DECOLA1",0),p.getOrDefault("VOO1",0),p.getOrDefault("POUSO_DECOLA2",0),p.getOrDefault("POUSO_DECOLA3",0),p.getOrDefault("VOO2",0),recharge,Utils.packageQueue.size(),monitorDT.getAverageMetricValue("system","MMT"),monitorDT.getAverageMetricValue("system","throughput"),targetMmt,lastRecommendedFleet));}catch(IOException e){throw new UncheckedIOException(e);}}
    private double runScenario(SystemState s){double tokens=s.queue+s.A+s.B+s.C+s.D+s.E+s.F;String[][] ps={{"numDrones",""+s.numDrones},{"TOKENS",""+tokens},{"AD",""+s.ad},{"DEPOSITO",""+Math.abs(s.tamDeposito-Math.round(s.queue))},{"PACOTES",""+Math.round(s.queue)},{"DRONES",""+s.idle},{"A",""+s.A},{"B",""+s.B},{"C",""+s.C},{"D",""+s.D},{"E",""+s.E},{"F",""+s.F},{"EMPRESTIMO",""+s.emprestimo},{"DEVOLUCAO",""+s.devolucao},{"RECARGA",""+rechargeTime},{"DESLOCAMENTO",""+displacementTime},{"VOO",""+s.voo},{"POUSO_DECOL",""+s.pousoDecola}};for(String[]p:ps)spnSolver.changeParameter(p[0],p[1]);HashMap<String,NonExactResult>r=spnSolver.stationarySimulationSolve(0,0.05);double mmt=Double.MAX_VALUE;if(r!=null)for(Map.Entry<String,NonExactResult>e:r.entrySet())if(e.getKey().contains("MMT"))mmt=e.getValue().getMean();return mmt;}
    void runDigitalTwin(){if(mode!=ExecutionMode.DYNAMIC_DT)return;Map<String,Integer>p=places();SystemState s=new SystemState();s.tamDeposito=1000;s.ad=positiveOr(monitorDT.getAverageMetricValue("system","AD"),30_000);s.queue=Utils.packageQueue.size();s.pousoDecola=positiveOr(monitorDT.getAverageMetricValue("system","POUSO_DECOLA"),30_000);s.voo=positiveOr(monitorDT.getAverageMetricValue("system","VOO"),1_200_000);s.A=p.getOrDefault("POUSO_DECOLA1",0);s.B=p.getOrDefault("VOO1",0);s.C=p.getOrDefault("POUSO_DECOLA2",0);s.D=p.getOrDefault("POUSO_DECOLA3",0);s.E=p.getOrDefault("VOO2",0);s.F=count(DroneState.RECHARGING);s.emprestimo=count(DroneState.RENTING_TRANSIT);s.devolucao=count(DroneState.RETURNING_TRANSIT);s.idle=count(DroneState.AVAILABLE);int lo=Utils.minDrones,hi=Utils.maxDrones,best=hi;while(lo<=hi){int mid=lo+(hi-lo)/2;s.numDrones=mid;if(runScenario(s)<=targetMmt){best=mid;hi=mid-1;}else lo=mid+1;}long desired=best;
        // When the queue is empty, unused rented drones above the ready reserve are pure waste.
        if(s.queue==0 && s.idle>idleReserve) desired=Math.max(Utils.minDrones,operational()-((long)s.idle-idleReserve));
        lastRecommendedFleet=(int)desired;long committed=operational()+count(DroneState.RENTING_TRANSIT);if(desired>committed)requestRentals((int)(desired-committed));else if(desired<operational()){long alreadyLeaving=count(DroneState.RETURNING_TRANSIT)+pendingReturns;long newReturns=Math.max(0,operational()-desired-alreadyLeaving);requestReturns((int)newReturns);}System.out.printf(Locale.US,"[%.0f] DT: alvo MMT=%.0f ms, frota recomendada=%d, operacional=%d, ociosos=%.0f%n",currentTime,targetMmt,desired,operational(),s.idle);}
    private double positiveOr(double value, double fallback) { return value > 0 ? value : fallback; }
    void run(){FacadeUtil.disableWarning();if(mode==ExecutionMode.DYNAMIC_DT)spnSolver=new SPNsolver("modelo/model_drones_recarga.xml");resetSystemStateFile();if(mode==ExecutionMode.DYNAMIC_DT)runDigitalTwin();running=true;while(running&&!queueEvents.isEmpty()){SimEvent e=queueEvents.poll();currentTime=e.time;if(currentTime>simulationTime)break;if(e.name.startsWith("POUSO_DECOLA")||e.name.startsWith("VOO")){String place=e.name.equals("POUSO_DECOLA4")?"POUSO_DECOLA2":e.name;missionStates.put(e.proxyName,place);monitorDT.addMetric("system",e.name.startsWith("VOO")?"VOO":"POUSO_DECOLA",(float)e.value,System.currentTimeMillis());}else if(!e.name.equals("END"))monitorDT.addMetric("system",e.name,(float)e.value,System.currentTimeMillis());e.action.run();while(currentTime>=nextMetricSample){monitorDT.addMetric("system","QUEUE",(float)Utils.packageQueue.size(),System.currentTimeMillis());monitorDT.addMetric("system","throughput",(float)Utils.tp,System.currentTimeMillis());Utils.tp=0;nextMetricSample+=60_000;}while(currentTime>=nextDecisionCycle){runDigitalTwin();saveSystemState();nextDecisionCycle+=decisionInterval;}}}
}
